CREATE TABLE IF NOT EXISTS `accounts` (`id` TEXT NOT NULL, `providerId` TEXT NOT NULL, `email` TEXT NOT NULL, `displayName` TEXT NOT NULL, `displayEmail` TEXT, `avatarText` TEXT, `enabled` INTEGER NOT NULL, `authType` TEXT NOT NULL, `oauthAccountId` TEXT, `loginName` TEXT, `customImapHost` TEXT, `customImapPort` INTEGER, `customImapSecurity` TEXT, `customSmtpHost` TEXT, `customSmtpPort` INTEGER, `customSmtpSecurity` TEXT, `customAuthMechanism` TEXT, `sortOrder` INTEGER NOT NULL DEFAULT 0, `createdAt` INTEGER NOT NULL, `lastSyncAt` INTEGER, `lastError` TEXT, PRIMARY KEY(`id`));
CREATE TABLE IF NOT EXISTS `folders` (`id` TEXT NOT NULL, `accountId` TEXT NOT NULL, `remoteName` TEXT NOT NULL, `canonicalType` TEXT NOT NULL, `uidValidity` INTEGER NOT NULL, `uidNext` INTEGER NOT NULL, `messageCount` INTEGER NOT NULL, `unreadCount` INTEGER NOT NULL, `lastSyncAt` INTEGER, PRIMARY KEY(`id`));
CREATE UNIQUE INDEX IF NOT EXISTS `index_folders_accountId_remoteName` ON `folders` (`accountId`, `remoteName`);
CREATE TABLE IF NOT EXISTS `messages` (`id` TEXT NOT NULL, `accountId` TEXT NOT NULL, `folderType` TEXT NOT NULL, `remoteFolder` TEXT NOT NULL, `remoteUid` INTEGER NOT NULL, `internetMessageId` TEXT, `senderName` TEXT NOT NULL, `senderAddress` TEXT NOT NULL, `recipients` TEXT NOT NULL, `cc` TEXT NOT NULL, `subject` TEXT NOT NULL, `preview` TEXT NOT NULL, `bodyText` TEXT NOT NULL, `bodyHtml` TEXT, `bodyLoaded` INTEGER NOT NULL DEFAULT 1, `bodyParserVersion` INTEGER NOT NULL DEFAULT 0, `receivedAt` INTEGER NOT NULL, `unread` INTEGER NOT NULL, `starred` INTEGER NOT NULL, `hasAttachments` INTEGER NOT NULL, `attachmentsJson` TEXT NOT NULL DEFAULT '[]', `htmlContentHash` TEXT, `remoteImageAllowed` INTEGER NOT NULL, `deliveryState` TEXT NOT NULL DEFAULT 'REMOTE', PRIMARY KEY(`id`));
CREATE UNIQUE INDEX IF NOT EXISTS `index_messages_accountId_folderType_remoteUid` ON `messages` (`accountId`, `folderType`, `remoteUid`);
CREATE INDEX IF NOT EXISTS `index_messages_receivedAt` ON `messages` (`receivedAt`);
CREATE INDEX IF NOT EXISTS `index_messages_senderAddress` ON `messages` (`senderAddress`);
CREATE TABLE IF NOT EXISTS `outbox` (`id` TEXT NOT NULL, `accountId` TEXT NOT NULL, `recipients` TEXT NOT NULL, `cc` TEXT NOT NULL, `bcc` TEXT NOT NULL, `subject` TEXT NOT NULL, `bodyText` TEXT NOT NULL, `attachmentsJson` TEXT NOT NULL DEFAULT '[]', `internetMessageId` TEXT NOT NULL DEFAULT '', `state` TEXT NOT NULL, `remoteFolder` TEXT, `remoteUid` INTEGER, `sourceMessageId` TEXT, `retryCount` INTEGER NOT NULL, `lastError` TEXT, `createdAt` INTEGER NOT NULL, `updatedAt` INTEGER NOT NULL, PRIMARY KEY(`id`));
CREATE TABLE IF NOT EXISTS `notification_state` (`accountId` TEXT NOT NULL, `folderType` TEXT NOT NULL, `remoteUid` INTEGER NOT NULL, `notifiedAt` INTEGER NOT NULL, PRIMARY KEY(`accountId`, `folderType`, `remoteUid`));
CREATE TABLE IF NOT EXISTS `saved_contacts` (`id` TEXT NOT NULL, `name` TEXT NOT NULL, `email` TEXT NOT NULL, `avatarText` TEXT, `createdAt` INTEGER NOT NULL, `updatedAt` INTEGER NOT NULL, PRIMARY KEY(`id`));
CREATE UNIQUE INDEX IF NOT EXISTS `index_saved_contacts_email` ON `saved_contacts` (`email`);
